import { test, expect } from '@playwright/test';

test.describe('Table Row Filtering by Search Input', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should filter table rows correctly when user types in search input', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify initial row count
    const initialRows = page.getByRole('row').count();
    expect(initialRows).toBeGreaterThan(0);

    // Get search input by label
    const searchInput = page.getByLabel('Search table');
    await expect(searchInput).toBeVisible();

    // Type search term
    await searchInput.fill('John');

    // Wait for filter to apply
    await page.waitForTimeout(500);

    // Verify filtered rows are displayed
    const filteredRows = page.getByRole('row');
    const rowCount = await filteredRows.count();
    expect(rowCount).toBeLessThan(initialRows);

    // Verify filtered rows contain search term
    const allRows = page.locator('[data-testid="table-row"]');
    const rowsWithJohn = await allRows.filter({ hasText: /John/i }).count();
    expect(rowsWithJohn).toBeGreaterThan(0);

    // Verify non-matching rows are hidden
    const rowsWithoutJohn = await allRows.filter({ hasText: /Jane/i }).count();
    expect(rowsWithoutJohn).toBe(0);

    // Verify search input retains value
    await expect(searchInput).toHaveValue('John');
  });

  test('should clear filter when search input is emptied and display all rows', async ({ page }) => {
    // Get search input by label
    const searchInput = page.getByLabel('Search table');
    await expect(searchInput).toBeVisible();

    // Type search term
    await searchInput.fill('Alice');

    // Wait for filter to apply
    await page.waitForTimeout(500);

    // Verify filtered rows are displayed
    const filteredRows = page.getByRole('row');
    const rowCountAfterFilter = await filteredRows.count();
    expect(rowCountAfterFilter).toBeLessThan(10);

    // Clear search input
    await searchInput.clear();
    await searchInput.fill('');

    // Wait for filter to clear
    await page.waitForTimeout(500);

    // Verify all rows are displayed again
    const allRows = page.getByRole('row');
    const rowCountAfterClear = await allRows.count();
    expect(rowCountAfterClear).toBeGreaterThan(10);

    // Verify search input is empty
    await expect(searchInput).toHaveValue('');

    // Verify table header is visible
    const tableHeader = page.getByRole('columnheader');
    await expect(tableHeader).toBeVisible();
  });
});
